query VerifyPromotionTargets($ids: [ID!]!) {
  nodes(ids: $ids) {
    ... on Product {
      id
      title
      handle
      status
      totalInventory
      variants(first: 10) {
        nodes {
          id
          title
          availableForSale
          inventoryQuantity
        }
      }
    }
  }
}
